// Extract and validate input data
const inputData = $input.all()[0].json;

// Validate required fields
if (!inputData.task_description) {
  throw new Error('task_description is required');
}

// Set default values
const context = inputData.context || {};
const budgetConstraints = inputData.budget_constraints || { max_cost: 0.10 };

// Prepare data for Python node
return {
  task_description: inputData.task_description,
  context: context,
  budget_constraints: budgetConstraints,
  timestamp: new Date().toISOString(),
  request_id: $node["webhook-trigger"].json.request_id || Date.now().toString()
};

// Process the Python node output
const pythonOutput = $input.all()[0].json;

// Check if Python execution was successful
if (pythonOutput.error) {
  return {
    success: false,
    error: pythonOutput.error,
    timestamp: new Date().toISOString()
  };
}

// Extract the routing result
const routingResult = JSON.parse(pythonOutput.stdout || '{}');

// Format the response for the user
if (routingResult.success) {
  return {
    success: true,
    routing_summary: {
      task_type: routingResult.routing_summary.task_type,
      complexity: routingResult.routing_summary.complexity,
      selected_model: routingResult.routing_summary.selected_model,
      reasoning: routingResult.routing_summary.reasoning,
      total_cost: routingResult.routing_summary.total_cost
    },
    ai_response: routingResult.execution_result.response,
    model_used: routingResult.execution_result.model_used,
    alternatives: routingResult.llm_selection.alternatives,
    timestamp: new Date().toISOString()
  };
} else {
  return {
    success: false,
    error: routingResult.error || 'Unknown error occurred',
    timestamp: new Date().toISOString()
  };
}

// Log the routing decision for monitoring
const routingData = $input.all()[0].json;

if (routingData.success) {
  console.log(`✅ Dynamic LLM Routing Success:`);
  console.log(`   Task Type: ${routingData.routing_summary.task_type}`);
  console.log(`   Complexity: ${routingData.routing_summary.complexity}`);
  console.log(`   Selected Model: ${routingData.routing_summary.selected_model}`);
  console.log(`   Cost: $${routingData.routing_summary.total_cost}`);
  console.log(`   Reasoning: ${routingData.routing_summary.reasoning}`);
} else {
  console.error(`❌ Dynamic LLM Routing Failed: ${routingData.error}`);
}

// Pass through the data
return routingData;
